    [5967]={name="Girdle of Nobility",quality=2,ilvl=18,reqLevel=13,sourceType="world_drop",instructions="Drops from Brainwashed Noble (rare spawn).",zone="The Deadmines",npc="Brainwashed Noble"},
    [5975]={name="Ruffian Belt",quality=2,ilvl=23,reqLevel=18,sourceType="world_drop",instructions="Drops from Rot Hide Bruiser (rare spawn).",zone="Fenris Isle",npc="Rot Hide Bruiser"},
    [6085]={name="Footman Tunic",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: \"Hogger\"'. Pick it over the other reward choices.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
    [6092]={name="Black Whelp Boots",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Underbelly Scales'. Pick it over the other reward choices. Starts with Verner Osgood in Redridge Mountains. Objective: Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.",zone="Redridge Mountains",questName="Underbelly Scales",lore="I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire."},
    [6093]={name="Orc Crusher",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Tharil'zun'. Pick it over the other reward choices.",zone="Redridge Mountains",questName="Tharil'zun",lore="Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep. The leader of the Outrunners is an orc named Tharil'zun--we want this orc."},
    [6095]={name="Wandering Boots",quality=2,ilvl=24,sourceType="quest_reward",instructions="Reward from the quest 'Return to Kristoff'. Starts with Brother Paxton in Stormwind City. Objective: Return to Brother Kristoff in the Cathedral Square. Give him the book The Stresses of Iron.",zone="Stormwind City",questName="Return to Kristoff",lore="Now that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay."},
    [6191]={name="Kimbra Boots",quality=2,ilvl=23,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Chok'sul'. Pick it over the other reward choices.",zone="Loch Modan",questName="WANTED: Chok'sul",lore="By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."},
    [6197]={name="Loch Croc Hide Vest",quality=2,ilvl=22,reqLevel=17,sourceType="world_drop",instructions="Drops from Large Loch Crocolisk (rare spawn).",zone="The Loch",npc="Large Loch Crocolisk"},
