    [12254]={name="Well Oiled Cloak",quality=2,ilvl=44,reqLevel=39,sourceType="vendor",instructions="Bought from Worb Strongstitch.",zone="Camp Mojache",npc="Worb Strongstitch"},
    [12255]={name="Pale Leggings",quality=2,ilvl=46,reqLevel=41,sourceType="vendor",instructions="Bought from Thralosh.",zone="Stonard",npc="Thralosh"},
    [12256]={name="Cindercloth Leggings",quality=2,ilvl=49,reqLevel=44,sourceType="vendor",instructions="Bought from Vinasia.",zone="Darnassus",npc="Vinasia"},
    [12295]={name="Leggings of the People's Militia",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Red Leather Bandanas'. Pick it over the other reward choices. Starts with Scout Galiaan in Westfall. Objective: Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill.",zone="Westfall",questName="Red Leather Bandanas",lore="The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."},
    [12522]={name="Bingles' Flying Gloves",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Bingles' Missing Supplies'. Starts with Bingles Blastenheimer in Loch Modan. Objective: Find and return Bingles' supplies:Bingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.",zone="Loch Modan",questName="Bingles' Missing Supplies",lore="As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives."},
    [12542]={name="Funeral Pyre Vestment",quality=3,ilvl=51,reqLevel=46,sourceType="world_drop",instructions="World drop around level 48-56."},
    [12547]={name="Mar Alom's Grip",quality=3,ilvl=56,reqLevel=51,sourceType="world_drop",instructions="World drop around level 48-56."},
