    [20216]={name="Belt of Preserved Heads",quality=3,ilvl=70,sourceType="quest_reward",instructions="Reward from the quest 'A Collection of Heads'. Pick it over the other reward choices. Starts with Exzhal in Stranglethorn Vale. Objective: String 5 Channeler's Heads, then return the Collection of Troll Heads to Exzhal on Yojamba Isle.",zone="Zul'Gurub",questName="A Collection of Heads",lore="He must be stopped! Take this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy."},
