    [22348]={name="Doomulus Prime",quality=3,ilvl=65,sourceType="quest_reward",instructions="Reward from the quest 'The Perfect Poison'. Pick it over the other reward choices.",zone="Silithus",questName="The Perfect Poison",lore="My brother and I run the poison operations out of the manor Ravenholdt."},
    [22384]={name="Persuader",quality=4,ilvl=63,reqLevel=58,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [22399]={name="Idol of Health",quality=4,ilvl=78,reqLevel=60,sourceType="boss_drop",instructions="Drops from Viscidus.",zone="Temple of Ahn'Qiraj",npc="Viscidus",lore="A living mass of qiraji poison. It has to be frozen solid and then shattered, which is not how most things die."},
    [22488]={name="Dreamwalker Tunic",quality=4,ilvl=92,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Dreamwalker Tunic'. Starts with Rayne in Eastern Plaguelands. Objective: Rayne at Light's Hope Chapel in the Eastern Plaguelands will make a Dreamwalker Tunic if you bring her the following: 1 Desecrated Tunic, 25 Wartorn Leather Scraps, 6 Cured Rugged Hides and 2 Nexus Crystals.",zone="Naxxramas",questName="Dreamwalker Tunic",lore="From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes."},
    [22489]={name="Dreamwalker Legguards",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Dreamwalker Legguards'. Starts with Rayne in Eastern Plaguelands. Objective: Rayne at Light's Hope Chapel in the Eastern Plaguelands will make Dreamwalker Legguards if you bring her the following: 1 Desecrated Legguards, 20 Wartorn Leather Scraps, 8 Cured Rugged Hides and 1 Nexus Crystal.",zone="Naxxramas",questName="Dreamwalker Legguards",lore="From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes."},
